mapper.select:
select * from (
    select c.*,
        row_number() over (partition by parent_id order by created_at asc) as rn
    from comments c
    where parent_id in

        #{id}

    and is_deleted = 0
) t where rn <= #{limit}

select c.id as commentId, c.likes_count as likesCount, count(r.id) as count from comments c left join comments r on r.parent_id = c.id and r.is_deleted = 0 where c.id in
#{id}
and c.is_deleted = 0 group by c.id, c.likes_count
